```php
public static function create($uri, string $method = 'GET', array $parameters = [], array $cookies = [], array $files = [], array $server = [], $content = null): static
{
    $parts = parse_url($uri);
    // ...

    $_SERVER = array_replace([
        'SERVER_NAME' => 'localhost',
        'SERVER_PORT' => 80,
        'HTTP_HOST' => 'localhost',
        'HTTP_USER_AGENT' => 'Symfony',
        'HTTP_ACCEPT' => 'text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8',
        'HTTP_ACCEPT_LANGUAGE' => 'en-us,en;q=0.5',
        'HTTP_ACCEPT_CHARSET' => 'ISO-8859-1,utf-8;q=0.7,*;q=0.7',
        'REMOTE_ADDR' => '127.0.0.1',
        'SCRIPT_NAME' => '',
        'SCRIPT_FILENAME' => '',
        'SERVER_PROTOCOL' => 'HTTP/1.1',
        'REQUEST_TIME' => time(),
        'REQUEST_TIME_FLOAT' => microtime(true),
    ], $server);

    $_SERVER['PATH_INFO'] = $parts['path'] ?? '';
    $_SERVER['REQUEST_METHOD'] = strtoupper($method);

    // ...

    $headers = new HeaderBag($requestHeaders);

    $request = new static($queryParameters, $requestParameters, $cookies, $files, $headers->all());
    // ...
